"use strict";(self.webpackChunkfrontend=self.webpackChunkfrontend||[]).push([[7029],{7029(e,t,o){o.r(t),o.d(t,{default:()=>h});const h={1:[{verse:1,text:"The proverbs of Solomon the son of David, king of Israel;"},{verse:2,text:"To know wisdom and instruction; to perceive the words of understanding;"},{verse:3,text:"To receive the instruction of wisdom, justice, and judgment, and equity;"},{verse:4,text:"To give subtilty to the simple, to the young man knowledge and discretion."},{verse:5,text:"A wise man will hear, and will increase learning; and a man of understanding shall attain unto wise counsels:"},{verse:6,text:"To understand a proverb, and the interpretation; the words of the wise, and their dark sayings."},{verse:7,text:"The fear of the Lord is the beginning of knowledge: but fools despise wisdom and instruction."},{verse:8,text:"My son, hear the instruction of thy father, and forsake not the law of thy mother:"},{verse:9,text:"For they shall be an ornament of grace unto thy head, and chains about thy neck."},{verse:10,text:"My son, if sinners entice thee, consent thou not."},{verse:11,text:"If they say, Come with us, let us lay wait for blood, let us lurk privily for the innocent without cause:"},{verse:12,text:"Let us swallow them up alive as the grave; and whole, as those that go down into the pit:"},{verse:13,text:"We shall find all precious substance, we shall fill our houses with spoil:"},{verse:14,text:"Cast in thy lot among us; let us all have one purse:"},{verse:15,text:"My son, walk not thou in the way with them; refrain thy foot from their path:"},{verse:16,text:"For their feet run to evil, and make haste to shed blood."},{verse:17,text:"Surely in vain the net is spread in the sight of any bird."},{verse:18,text:"And they lay wait for their own blood; they lurk privily for their own lives."},{verse:19,text:"So are the ways of every one that is greedy of gain; which taketh away the life of the owners thereof."},{verse:20,text:"Wisdom crieth without; she uttereth her voice in the streets:"},{verse:21,text:"She crieth in the chief place of concourse, in the openings of the gates: in the city she uttereth her words, saying,"},{verse:22,text:"How long, ye simple ones, will ye love simplicity? and the scorners delight in their scorning, and fools hate knowledge?"},{verse:23,text:"Turn you at my reproof: behold, I will pour out my spirit unto you, I will make known my words unto you."},{verse:24,text:"Because I have called, and ye refused; I have stretched out my hand, and no man regarded;"},{verse:25,text:"But ye have set at nought all my counsel, and would none of my reproof:"},{verse:26,text:"I also will laugh at your calamity; I will mock when your fear cometh;"},{verse:27,text:"When your fear cometh as desolation, and your destruction cometh as a whirlwind; when distress and anguish cometh upon you."},{verse:28,text:"Then shall they call upon me, but I will not answer; they shall seek me early, but they shall not find me:"},{verse:29,text:"For that they hated knowledge, and did not choose the fear of the Lord:"},{verse:30,text:"They would none of my counsel: they despised all my reproof."},{verse:31,text:"Therefore shall they eat of the fruit of their own way, and be filled with their own devices."},{verse:32,text:"For the turning away of the simple shall slay them, and the prosperity of fools shall destroy them."},{verse:33,text:"But whoso hearkeneth unto me shall dwell safely, and shall be quiet from fear of evil."}],3:[{verse:1,text:"My son, forget not my law; but let thine heart keep my commandments:"},{verse:2,text:"For length of days, and long life, and peace, shall they add to thee."},{verse:3,text:"Let not mercy and truth forsake thee: bind them about thy neck; write them upon the table of thine heart:"},{verse:4,text:"So shalt thou find favour and good understanding in the sight of God and man."},{verse:5,text:"Trust in the Lord with all thine heart; and lean not unto thine own understanding."},{verse:6,text:"In all thy ways acknowledge him, and he shall direct thy paths."},{verse:7,text:"Be not wise in thine own eyes: fear the Lord, and depart from evil."},{verse:8,text:"It shall be health to thy navel, and marrow to thy bones."},{verse:9,text:"Honour the Lord with thy substance, and with the firstfruits of all thine increase:"},{verse:10,text:"So shall thy barns be filled with plenty, and thy presses shall burst out with new wine."},{verse:11,text:"My son, despise not the chastening of the Lord; neither be weary of his correction:"},{verse:12,text:"For whom the Lord loveth he correcteth; even as a father the son in whom he delighteth."},{verse:13,text:"Happy is the man that findeth wisdom, and the man that getteth understanding."},{verse:14,text:"For the merchandise of it is better than the merchandise of silver, and the gain thereof than fine gold."},{verse:15,text:"She is more precious than rubies: and all the things thou canst desire are not to be compared unto her."},{verse:16,text:"Length of days is in her right hand; and in her left hand riches and honour."},{verse:17,text:"Her ways are ways of pleasantness, and all her paths are peace."},{verse:18,text:"She is a tree of life to them that lay hold upon her: and happy is every one that retaineth her."},{verse:19,text:"The Lord by wisdom hath founded the earth; by understanding hath he established the heavens."},{verse:20,text:"By his knowledge the depths are broken up, and the clouds drop down the dew."},{verse:21,text:"My son, let not them depart from thine eyes: keep sound wisdom and discretion:"},{verse:22,text:"So shall they be life unto thy soul, and grace to thy neck."},{verse:23,text:"Then shalt thou walk in thy way safely, and thy foot shall not stumble."},{verse:24,text:"When thou liest down, thou shalt not be afraid: yea, thou shalt lie down, and thy sleep shall be sweet."},{verse:25,text:"Be not afraid of sudden fear, neither of the desolation of the wicked, when it cometh."},{verse:26,text:"For the Lord shall be thy confidence, and shall keep thy foot from being taken."},{verse:27,text:"Withhold not good from them to whom it is due, when it is in the power of thine hand to do it."},{verse:28,text:"Say not unto thy neighbour, Go, and come again, and to morrow I will give; when thou hast it by thee."},{verse:29,text:"Devise not evil against thy neighbour, seeing he dwelleth securely by thee."},{verse:30,text:"Strive not with a man without cause, if he have done thee no harm."},{verse:31,text:"Envy thou not the oppressor, and choose none of his ways."},{verse:32,text:"For the froward is abomination to the Lord: but his secret is with the righteous."},{verse:33,text:"The curse of the Lord is in the house of the wicked: but he blesseth the habitation of the just."},{verse:34,text:"Surely he scorneth the scorners: but he giveth grace unto the lowly."},{verse:35,text:"The wise shall inherit glory: but shame shall be the promotion of fools."}]}}}]);
